# openEMS return-current case (auto-generated by FluxPCB)
# Run: python return_current.py   (needs openEMS + CSXCAD python bindings)
# Dumps plane current density J under the trace; view J in ParaView.
import numpy as np
import openems
import CSXCAD

unit = 1e-3  # mm
FDTD = openems.OpenEMS(unit=unit, end_criteria=2000)
FDTD.SetGaussPulse(3e9, f0=1.5e9)
csx = FDTD.csx

h = 0.2      # dielectric thickness (mm)
t = 0.035
w = 0.3      # trace width (mm)
L = 40          # trace length (mm)
gnd_w = 60

# substrate box
sub = csx.AddMaterial(" substrate", epsilon=4.4)
sub.AddBox(xs=-30, ys=-5, zs=0, xe=30, ye=L+5, ze=h)

# ground plane + trace (PEC)
gnd = csx.AddMetal(" gnd"); gnd.AddBox(xs=-30, ys=-5, zs=0, xe=30, ye=L+5, ze=0)
trc = csx.AddMetal(" trace"); trc.AddBox(xs=-w/2, ys=0, zs=h, xe=w/2, ye=L, ze=h)

# ports (MSL) at both ends
port = openems.Port(csx, p_type=0, exc=-1, prop_dir=1, MSL_L=w, priority=6)
port.Direction = 1
FDTD.AddPort(port)

csx.AddDump("J", dump_type=3)  # current density on ground plane
FDTD.Run("sim_return", verbose=1)
print("view J in ParaView: sim_return/*.vtk")
